

import tkinter as tk


WIDTH = 900
HEIGHT = 600


def dda_points(x1, y1, x2, y2):
    """Return raster points generated by the DDA algorithm."""
    dx = x2 - x1
    dy = y2 - y1
    steps = max(abs(dx), abs(dy))

    if steps == 0:
        return [(round(x1), round(y1))]

    x_increment = dx / steps
    y_increment = dy / steps
    x, y = float(x1), float(y1)

    points = []
    for _ in range(steps + 1):
        points.append((round(x), round(y)))
        x += x_increment
        y += y_increment
    return points


def bresenham_points(x1, y1, x2, y2):
    """Return raster points using integer Bresenham logic (all octants)."""
    dx = abs(x2 - x1)
    dy = abs(y2 - y1)
    sx = 1 if x1 < x2 else -1
    sy = 1 if y1 < y2 else -1
    error = dx - dy

    points = []
    while True:
        points.append((x1, y1))
        if x1 == x2 and y1 == y2:
            break

        twice_error = 2 * error
        if twice_error > -dy:
            error -= dy
            x1 += sx
        if twice_error < dx:
            error += dx
            y1 += sy
    return points


def draw_pixels(canvas, points, color, scale=1):
    """Draw each raster point as a small square on the Tkinter canvas."""
    for x, y in points:
        canvas.create_rectangle(
            x - scale, y - scale, x + scale, y + scale,
            fill=color, outline=color
        )


def main():
    root = tk.Tk()
    root.title("Experiment 1 - DDA and Bresenham Line Drawing")
    root.geometry(f"{WIDTH}x{HEIGHT}")

    canvas = tk.Canvas(root, width=WIDTH, height=HEIGHT, bg="white")
    canvas.pack(fill="both", expand=True)

    # Panel headings and divider
    canvas.create_text(225, 45, text="DDA LINE DRAWING",
                       font=("Arial", 16, "bold"), fill="#222222")
    canvas.create_text(675, 45, text="BRESENHAM LINE",
                       font=("Arial", 16, "bold"), fill="#222222")
    canvas.create_line(450, 75, 450, 540, fill="#999999", width=2)

    # Draw DDA line in the left panel.
    dda = dda_points(100, 420, 350, 180)
    draw_pixels(canvas, dda, "#1769aa", scale=2)

    # Draw Bresenham line in the right panel.
    bresenham = bresenham_points(550, 420, 800, 180)
    draw_pixels(canvas, bresenham, "#d9482b", scale=2)

    canvas.create_text(225, 475, text="Start (100, 420)  ->  End (350, 180)",
                       font=("Arial", 10), fill="#333333")
    canvas.create_text(675, 475, text="Start (550, 420)  ->  End (800, 180)",
                       font=("Arial", 10), fill="#333333")
    canvas.create_text(450, 565,
                       text="Blue: DDA     |     Orange: Bresenham",
                       font=("Arial", 11), fill="#333333")

    print("Experiment 1: DDA and Bresenham Line Drawing")
    print("DDA pixels plotted:", len(dda))
    print("Bresenham pixels plotted:", len(bresenham))
    print("Close the graphics window to finish.")

    root.mainloop()


if __name__ == "__main__":
    main()
